// ClockEntryValidationTests.cs
public sealed class ClockEntryValidationTests
{
    [Fact]
    public void ClockOutEntry_WhenAlreadyComplete_ThrowsInvalidOperationException()
    {
        var clockEntry = new ClockEntry(1, new DateTime(2026, 8, 12, 9, 0, 0));
        clockEntry.ClockOutEntry(new DateTime(2026, 8, 12, 17, 0, 0));

        InvalidOperationException error = Assert.Throws<InvalidOperationException>(
            () => clockEntry.ClockOutEntry(new DateTime(2026, 8, 12, 18, 0, 0)));

        Assert.Contains("already complete", error.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void GetDuration_WhenEntryIsOpen_ThrowsInvalidOperationException()
    {
        var clockEntry = new ClockEntry(1, new DateTime(2026, 8, 12, 9, 0, 0));

        InvalidOperationException error = Assert.Throws<InvalidOperationException>(
            () => clockEntry.GetDuration());

        Assert.Contains("clock out", error.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void TryClockOut_WhenNoOpenEntryExists_ReturnsFalse()
    {
        var repository = new ClockEntryRepository();
        var service = new ClockEntryService(repository);

        bool result = service.TryClockOut(1, new DateTime(2026, 8, 12, 17, 0, 0));

        Assert.False(result);
    }

    [Fact]
    public void ClockOutEntry_WhenClockOutPrecedesClockIn_ThrowsArgumentOutOfRangeException()
    {
        var clockEntry = new ClockEntry(1, new DateTime(2026, 8, 12, 9, 0, 0));
        var clockOut = new DateTime(2026, 8, 12, 8, 59, 0);

        ArgumentOutOfRangeException error = Assert.Throws<ArgumentOutOfRangeException>(
            () => clockEntry.ClockOutEntry(clockOut));

        Assert.Equal("clockOut", error.ParamName);
        Assert.Contains("earlier than clock-in", error.Message, StringComparison.OrdinalIgnoreCase);
    }
}
